custom_css:
@import url("https://fontsapi.zeoseven.com/79/main/result.css");

body {
    font-family: "Clear Han Serif";
    font-weight: normal;
}
/* =========================================
   原代码框架@毛毛雨，雨水一盒@masaka
   ========================================= */
:root {
    --输入框文案: "全世界的水都会重逢";
    --思维链标题: "The whole world's waters will meet again; the Arctic Ocean and the Nile will mingle in the wet clouds.";
    --抽屉高度: 0px;    /* 打开顶栏菜单面板时，面板与顶栏有空隙改这个*/
    --头像显示位置: center top;
    --文本两侧间距: 5%;
    --头像圆圈大小: 80%;
    --头像上下: 6%;      
    --头像左右位置: 32%;
    --名字上下: 3%;                /
    --名字左右: 5%;               
    --名字后缀文案: "Ripple";     
    --名字后缀上下: 30%;           
    --时间戳上下: 6%;             
    --时间戳左右: 44%;            
    --三元素上下: 6%;             
    --三元素1左右: 79%;           
    --三元素2左右: 84%;           
    --三元素3左右: 90%;           
    --上间距: 8px;
    --下间距: 8px;
    --输入框字号: 12px;
    --输入框行高: 1;
}

/* =========================================
   1. 🐰 全局布局与基础设置｜@NAKARI
   ========================================= */

/* 隐藏滚动条 */
::-webkit-scrollbar {
    display: none;
}

/* 选中文本的颜色 */
::selection {
    background: #adadad;
}

/* 禁止文本域拉伸 */
textarea,
#send_textarea {
    resize: none;
}

/* 全局重置 */
* {
    filter: none !important;
    outline: none !important;
}

/* 弹窗阴影去除 */
#select_chat_popup,
.popup,
.popper-modal {
    box-shadow: none !important;
}

/* --- 背景菜单区域 --- */
#bg-header-fixed,
#bg_tabs {
    background: none;
}
#backgrounds-button *{
    box-shadow: none;
}

/* --- 聊天主区域 --- */
#chat {
    border: none !important;
    max-height: calc(100dvh + var(--bottomFormBlockSize));
    height: calc(100dvh + var(--bottomFormBlockSize));
    padding-top: 30px !important;
    padding-bottom: 120px !important;
background: none !important;

}

/* --- 遮罩层 --- */
#sheld {
    top: var(--bottomFormBlockSize);
    height: calc(100dvh - var(--bottomFormBlockSize));
    max-height: calc(100dvh - var(--bottomFormBlockSize));
    min-height: calc(100dvh - var(--bottomFormBlockSize));
}

/* --- 抽屉面板容器 --- */

.drawer-content {
    background-image:
        linear-gradient(rgba(255,255,255,0.6), rgba(255,255,255,0.6)),
        url('https://i.postimg.cc/8cQPqpdx/IMG-9622.jpg') !important;
    background-size: cover, cover !important;
    background-position: center, center !important;
    background-repeat: no-repeat, no-repeat !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 8px 8px 20px 8px !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    top: var(--抽屉高度) !important;
}



/* --- 左右侧边栏布局 --- */
#left-nav-panel,
#right-nav-panel {
    height: calc(100dvh - var(--topBarBlockSize)) !important;
    top: var(--抽屉高度) !important;
}


/* =========================================
   2. 消息主体部分 (Message)
   ========================================= */

/* 修复最后一条消息间距｜@Serein */
.mes.last_mes > *:has(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}


/* --- 消息主体样式 --- */
.mes {
    position: relative !important;
    overflow: visible !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;

    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    background: none !important;
    padding: 101% 0px 68% 0px !important;    
    margin: 5px auto 50px auto !important;
    width: 100%;
}

/* 平铺层 */
.mes::before {
    content: "";
    position: absolute;
    top: 0;    margin-top: 101%;   
    bottom: 0; margin-bottom: 0%;  
    left: 0;
    right: 0;
    z-index: -2;
    pointer-events: none;

    background-image: url('https://i.postimg.cc/gjRdczTQ/wei-ming-ming-zuo-pin.png') !important;
    background-repeat: repeat-y !important;
    background-position: top center !important;
    background-size: 100% auto !important;
}

/* 头图+尾图 */
.mes::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 2;
    pointer-events: none;

    background-image:
        url('https://i.postimg.cc/Y2XCd06M/wei-ming-ming-zuo-pin.png'),
        url('https://i.postimg.cc/nzjmYWrX/IMG-9544.png') !important;
    background-repeat: no-repeat, no-repeat !important;
    background-position: top center, bottom center !important;
    background-size: 100% auto, 100% auto !important;
}

.last_mes {
    margin-bottom: 65px !important;
}


/* --- 消息块 --- */
.mes_block {
    overflow: visible !important;
    position: static; 
    width: 100% !important;
    margin: 0 !important;
    padding: 0 var(--文本两侧间距) !important;
    z-index: 5;
}


/* --- 消息头像 --- */

/* 头像容器  */
.mes .avatar {
    position: absolute !important;
    pointer-events: none;
    opacity: 1 !important;
    aspect-ratio: 1560 / 2030;   
    width: 100% !important;
    height: auto !important;
    top: 0px !important;
    left: 0 !important;
    z-index: 0;  
}

/* 头像图片 */
.mes .avatar img {
    position: absolute !important;
    border: none !important;
    box-shadow: none !important;
    object-fit: cover !important;
    object-position: var(--头像显示位置);

    aspect-ratio: 1228 / 1236;
    width: var(--头像圆圈大小) !important;
    height: auto !important;
    left: var(--头像左右位置) !important;
    top: var(--头像上下) !important;
    transform: translateX(-50%) !important;

    border-radius: 0 !important;
    z-index: 0 !important;
}

/* 纹理图*/
.mes .avatar::after {
    content: "";
    position: absolute;
    aspect-ratio: 1228 / 1236;
    width: var(--头像圆圈大小) !important;
    height: auto !important;
    left: var(--头像左右位置) !important;
    top: var(--头像上下) !important;
    transform: translateX(-50%) !important;
    border-radius: 0 !important;
    z-index: 1;        /* 头像上方 */
    pointer-events: none;

    background-image: url('https://i.postimg.cc/y6cCnJnk/wei-ming-ming-zuo-pin.png') !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: 100% 100% !important;
}



/* --- 消息文本 --- */
.mes_text {
    text-align: justify !important;
    line-height: 1.7 !important;   
    letter-spacing: 0.2px;          
    margin: 0 !important;
    padding: 0px !important;
}

/* 段间距 💙 */
.mes p:not(:last-child) {
    margin-bottom: 1.3em !important;
}


/* --- 名字 --- */

.name_text {
    position: absolute !important;
    display: flex !important;
    justify-content: flex-start !important;
    align-items: center !important;
    white-space: nowrap;

    letter-spacing: 1px;
    font-weight: normal !important;
    font-size: 11px !important;
    color: #aaa39e !important;
    -webkit-text-stroke: 1.5px white;
    paint-order: stroke fill;
    filter: drop-shadow(0.5px 0.5px 0px #707070) !important;

    top: 0px;
    margin-top: var(--名字上下) !important;
    left: var(--名字左右) !important;
    z-index: 10;
}

.name_text::after {
    content: var(--名字后缀文案);
    position: absolute;
    top: 100%;
    margin-top: 3px;
    left: 0;
    white-space: nowrap;

    letter-spacing: 0.5px;
    font-size: 8px;
    color: #bab5b1;
    -webkit-text-stroke: 1.2px white;
    paint-order: stroke fill;
    filter: drop-shadow(0.5px 0.5px 0px #707070) !important;
    z-index: 10;
}


/* --- 时间戳 --- */
.timestamp {
    position: absolute;
    white-space: nowrap;
    top: 0px;
    margin-top: var(--时间戳上下) !important;
    left: var(--时间戳左右) !important;

    font-size: 8px;
    color: #b6b0ac !important;
    -webkit-text-stroke: 1.5px white;
    paint-order: stroke fill;
    filter: drop-shadow(0.5px 0.5px 0px #707070) !important;
    opacity: 1 !important;
    z-index: 10;
}


/* --- 三元素 --- */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
    position: absolute;
    top: 0px;
    margin-top: var(--三元素上下) !important;
    font-size: 8px !important;
    font-weight: normal !important;
    opacity: 0.9 !important;
    color: #b7b1ad;
    -webkit-text-stroke: 1.5px white;
    paint-order: stroke fill;
    filter: drop-shadow(0.5px 0.5px 0px #707070) !important;
    z-index: 10;
}

.mesIDDisplay {
    left: var(--三元素1左右) !important;
}
.tokenCounterDisplay {
    left: var(--三元素2左右) !important;
}
.mes_timer {
    left: var(--三元素3左右) !important;
}

.mesIDDisplay::before { content: "· "; }
.tokenCounterDisplay::before { content: "· "; }
.mes_timer::before { content: "· "; }

/* --- 消息编辑按钮 --- */

.mes_buttons,
.extraMesButtons {
    overflow: visible !important;
}

.mes_buttons {
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    position: absolute !important;
    bottom: -8px !important;
    right: 10px !important;
    gap: 4px;
    z-index: 100;
    color: #4a5560 !important;
}

.mes_buttons .fa-ellipsis::before,
.mes_buttons .fa-pencil::before {
    content: "";
}

.mes_buttons .fa-pencil {
    background: url('https://i.postimg.cc/8cFcRgnB/wei-ming-ming-zuo-pin.png') center/contain no-repeat !important;
    width: 60px;
    height: 60px;
}

.mes_buttons .fa-ellipsis {
    background: url('https://i.postimg.cc/cLWYS6zN/wei-ming-ming-zuo-pin.png') center/contain no-repeat !important;
    width: 80px;
    height: 80px;
}

.extraMesButtons {
    position: relative !important;
    gap: 7px;
}
.extraMesButtons>div {
    opacity: 1 !important;
    color: #4a5560;
    padding: 3px 5px;
    border-radius: 6px !important;
    background: rgba(238, 242, 245, 0.7) !important;  
    border: 1.5px solid rgba(180, 195, 205, 0.5) !important;
    box-shadow: 1px 1px 4px rgba(90, 110, 130, 0.15) !important;
}

.mes_edit_buttons {
    position: absolute !important;
    gap: 8px;
    bottom: 115px;
    left: 50% !important;
    transform: translateX(-50%) !important;
}
.mes_edit_buttons .menu_button {
    opacity: 1;
}


/* --- 思维链 --- */

.mes_reasoning_header {
    position: absolute !important;
    display: flex !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    top: 0px;
    margin-top: 85%;
    left: 9%;
    width: 35%;
    padding: 0 !important;
    background: none !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    z-index: 10;
}

.mes_reasoning_header_title {
    font-size: 0 !important;
}
.mes_reasoning_header_title::after {
    content: var(--思维链标题);
    display: block;
    white-space: normal;
    word-break: break-word;
    font-size: 7px;
    line-height: 1.6;
    letter-spacing: 0.6px;
    color: #5c5c5c;
    -webkit-text-stroke: 2px white;
    paint-order: stroke fill;
    filter: drop-shadow(1px 1px 0px #999999) !important;
}

.mes_reasoning_arrow {
    display: none !important;
}



/* --- 翻页按钮 --- */

.swipeRightBlock {
    display: contents !important;
}

.mes .swipe_left,
.mes .swipe_right {
    position: absolute !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    width: 60px !important;
    height: 30px !important;
    padding: 0px !important;
    background: #c2c2c2 !important;
    border: 1.5px solid white !important;
    outline: 1.3px solid #5c5c5c !important;
    box-shadow: 0px 2px 2px #333333 !important;
    border-radius: 100px !important;
    font-family: inherit !important;
    font-weight: normal;
    font-size: 10px !important;
    opacity: 1 !important;
    bottom: -35px !important;
    transition: all 0.5s ease !important;
}

.mes .swipe_left::before,
.mes .swipe_right::before {
    letter-spacing: 1px;
    color: #474747 !important;
    -webkit-text-stroke: 1.5px white;
    paint-order: stroke fill;
    filter: drop-shadow(0.5px 0.5px 0px #333333) !important;
}
.mes .swipe_left::before { content: "◁" }
.mes .swipe_right::before { content: "▷" }

.mes .swipe_left { left: 10px; }
.mes .swipe_right { right: 10px; }

.mes .swipe_left:active,
.mes .swipe_right:active {
    transform: translateY(5px) scale(0.85) !important;
    opacity: 0.3 !important;
}

.mes .swipes-counter {
    position: absolute !important;
    font-size: 8px !important;
    color: #474747;
    -webkit-text-stroke: 1.5px white;
    paint-order: stroke fill;
    filter: drop-shadow(0.5px 0.5px 0px #333333) !important;
    bottom: 8px!important;
    left: 50% !important;
    transform: translateX(-50%);
    right: auto !important;

    z-index: 100;
    opacity: 1 !important;
}


/* --- 消息删除勾选框 --- */
.del_checkbox {
    position: absolute !important;
    opacity: 1 !important;
    z-index: 100;
    top: 170px;
    left: 20px !important;
}


/* --- Markdown 元素 --- */

.mes ul,
.mes ol {
    padding-left: 1em !important;
}

.mes q {
    background: #e8ecef !important;
    border-radius: 3px !important;
}

blockquote {
    position: relative !important;
    overflow: hidden !important;

    background: rgba(255,255,255,.82) !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;

    border: 1px solid rgba(180,195,205,.55) !important;
    border-radius: 18px !important;

    box-shadow:
        0 8px 24px rgba(90,110,130,.10),
        inset 0 1px rgba(255,255,255,.8) !important;

    padding: 46px 24px 36px !important;
    margin: 18px 0 !important;

    color: #4a5560 !important;
    line-height: 1.9 !important;
    font-size: 15px !important;
}

blockquote::before {
    content: "";
    position: absolute;
    top: 14px;
    left: 24px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background:
        radial-gradient(circle at center, #fff 0 3px, transparent 3.5px),
        conic-gradient(from 0deg, #b0c0cc 0 25%, #dbe3e8 0 50%, #b0c0cc 0 75%, #dbe3e8 0 100%);
    box-shadow: 0 0 0 1px rgba(150,170,185,.4);
}

blockquote::after {
    content: "SIDE A · TRACK 01" !important;

    position: absolute;
    top: 16px;
    left: 48px;
    right: 24px;

    font-size: 11px;
    letter-spacing: .18em;
    font-weight: 600;

    color: #7a92a4;

    padding-bottom: 8px;
    border-bottom: 1px solid rgba(150,170,185,.45);
}

code {
    font-size: 0.95em;
    background: #eef2f5 !important;
    box-shadow: 1px 1.5px 2px rgba(90, 110, 130, 0.15) !important;
    border-radius: 0px;
    color: #4a6070 !important;
    padding: 1px 5px !important;
}

pre code {
    padding: 8px 12px !important;
    border-radius: 0px !important;
    background: #f6f9fb !important;
    border: 1.5px solid #93b0c0 !important;
    outline: none !important;
    box-shadow:
        0px 0px 0px 2.5px rgba(255, 255, 255, 1),
        1px 1px 2px 2.5px rgba(90, 110, 130, 0.25) !important;
    line-height: 1.5 !important;
}
pre code * {
    color: #2c4a5c !important;
}

hr {
    border: none !important;
    height: 27px !important;
    margin: 15px 0 !important;
    background: url('https://i.postimg.cc/05C7pjYz/wu-biao-ti19-20260702230412.png') center/contain no-repeat !important;
    opacity: 1 !important;
}

/* =========================================
   3. 🐰 顶栏 (Top Bar)
   ========================================= */

#top-bar,
body.no-blur #top-bar {
    background: none !important;
    box-shadow: none !important;
    border: none !important;
}
#top-settings-holder {
    height: 36px;
}

/* 顶栏背景 */
#top-bar::after {
    content: "";
    position: absolute;
    background-image: url('https://i.postimg.cc/QxBZpGpW/wu-biao-ti13-20260702203306.png') !important;
    background-size: 100% auto !important;
    background-repeat: no-repeat !important;
    background-position: top center;
    top: 0px;
    aspect-ratio: 1536 / 272 !important;
    width: 100%;
    height: auto;
}

/* 打开时恢复背景 */
body:has(.drawer-icon.openIcon) #top-settings-holder {
    background: rgba(238, 240, 242, 0.92) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    box-shadow: 0 2px 8px rgba(80, 90, 100, 0.12) !important;
}

.drawer-icon {
    opacity: 0 !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    height: 29px;
    padding: 0 15px !important;
    font-size: 14px;
    color: #5c6570 !important;
    background: none !important;
    box-shadow: none !important;
    transition: all 0.3s ease !important;
}

body:has(.drawer-icon.openIcon) .drawer-icon {
    opacity: 1 !important;
}

.drawer-icon.openIcon {
    color: #3f474f !important;
    background: none !important;
    box-shadow: none !important;
    transition: all 0.3s ease !important;
}



#leftNavDrawerIcon::before { content: "\f5ad"; }
#sys-settings-button .drawer-icon::before { content: "\f013"; }
#advanced-formatting-button .drawer-icon::before { content: "\f031"; }
#WI-SP-button .drawer-icon::before { content: "\f02d"; }
#user-settings-button .drawer-icon::before { content: "\f015"; }
#backgrounds-drawer-toggle .drawer-icon::before { content: "\f03e"; }
#logo_block .drawer-icon::before { content: "\f03e"; }
#extensions-settings-button .drawer-icon::before { content: "\f552"; }
#persona-management-button .drawer-icon::before { content: "\f5a4"; }
#rightNavDrawerIcon::before { content: "\f2b9"; }


/* =========================================
   4. 🐰 底部输入区域 (Bottom Input)
   ========================================= */


/* 两侧按钮组 */
#leftSendForm,
#rightSendForm {
    justify-content: center !important;
    align-items: end !important;
    gap: 2px !important;

}

/* 底栏悬浮定位 */
#form_sheld {
    position: absolute;
    bottom: 0px;
}

/* 输入框容器 */
#send_form,
body.no-blur #send_form {
    width: calc(100% - 24px);
    margin: 0px auto 10px auto;
    background:
        url('https://i.postimg.cc/s295wgk0/IMG-9545.png') center/140% repeat,
        rgba(238, 240, 242, 0.6) !important;
    background-blend-mode: multiply;
    border-radius: 0 !important;
    border: 1px solid rgba(180, 195, 205, 0.5) !important;
    outline: 1.2px solid rgba(255, 255, 255, 1) !important;
    box-shadow:
        0px 2px 0px 0px rgba(200, 210, 218, 0.8),
        0px 2.8px 0px 0px rgba(220, 228, 233, 0.6),
        0px 2.2px 4px 2px rgba(90, 110, 130, 0.25) !important;
    padding: 6px 4px 6px 4px !important;
}

#leftSendForm,
#rightSendForm {
    justify-content: center !important;
    align-items: end !important;
    gap: 2px !important;
}

/* 文本输入域 */
#send_textarea {
    clip-path: none !important;
    background-image: linear-gradient(to right, transparent, rgba(120, 140, 160, 0.3) 50%, transparent) !important;
    background-size: 100% 0.9px !important;
    background-repeat: no-repeat !important;
    background-position: center bottom 2px !important;
    border: none !important;
    border-radius: 0px !important;
    box-shadow: none !important;
    padding: var(--上间距) 10px var(--下间距) 10px !important;
    line-height: var(--输入框行高) !important;
    font-size: var(--输入框字号);
    color: #4a5560 !important;
}



/* --- 底部按钮图标 --- */
.fa-bars::before,
#extensionsMenuButton::before,
.fa-paper-plane::before,
.fa-circle-stop::before {
    display: none !important;
    content: '' !important;
}

.fa-bars,
#extensionsMenuButton,
.fa-paper-plane,
.fa-circle-stop {
    opacity: 1 !important;
    width: 35px !important;
    height: 35px !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

/* 菜单按钮 */
.fa-bars {
    background-image: url('https://i.postimg.cc/tC2cYr1v/wu-biao-ti16-20260702212055.png');
}

/* 扩展按钮 */
#extensionsMenuButton {
    background-image: url('https://i.postimg.cc/Qx0zH6Bn/wu-biao-ti16-20260702212147.png');
}

/* 发送按钮 */
.fa-paper-plane {
    background-image: url('https://i.postimg.cc/bShYjT2G/wu-biao-ti16-20260702212204.png');
    margin-left: 2px !important;
    transform: scale(1.1);
}

